using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;
namespace ScoreModern {public sealed partial class Editor {
 internal void CheckZoomFramings(string output){Directory.CreateDirectory(output);var original=score.Encode();var modeBefore=NativeNotationView.Mode;bool dosBefore=NativeZoomFraming.Dos;try{
  foreach(bool dos in new[]{true,false})foreach(NotationView view in Enum.GetValues(typeof(NotationView)))foreach(float dpi in new[]{1f,1.75f,2f}){
   NativeNotationView.Set(view,false);NativeZoomFraming.Set(dos,false);canvas.OriginalZoomFrame=false;canvas.CameraOffset=PointF.Empty;canvas.DisplayDpi=dpi;viewport.AutoScrollMinSize=Size.Empty;viewport.AutoScrollPosition=Point.Empty;NativeDosViewport.Reset();canvas.Zoom=1;canvas.LayoutScore();mode=ScreenMode.Main;canvas.Selected=null;
   foreach(string command in new[]{"Z 1","Z 2","Z 2 20 30","ZR 10","ZU 5","ZD","ZL","ZZ 2","Z"}){Execute(command);if(!original.SequenceEqual(score.Encode()))throw new Exception("Zoom changed notation.");if(!dos&&view!=NotationView.DatViewport){
    if(canvas.CameraOffset.X<0||canvas.CameraOffset.Y<0)throw new Exception("Full-page zoom leaves unreachable negative coordinates.");
    var paper=canvas.ScreenPaper;float top=(paper.Top+canvas.CameraOffset.Y+canvas.ScreenOrigin.Y)*canvas.RenderScale-canvas.CropTop,bottom=(paper.Bottom+canvas.CameraOffset.Y+canvas.ScreenOrigin.Y)*canvas.RenderScale-canvas.CropTop;
    if(top<-.1||bottom>canvas.Height+1)throw new Exception("Zoom clips the paper outside its scroll canvas.");
    Point saved=viewport.AutoScrollPosition;viewport.AutoScrollPosition=new Point(0,Math.Max(0,(int)Math.Floor(top)));float visibleTop=top+viewport.AutoScrollPosition.Y;if(visibleTop< -1||visibleTop>viewport.ClientSize.Height+1)throw new Exception("Page top cannot be reached by scrolling.");
    viewport.AutoScrollPosition=new Point(0,Math.Max(0,(int)Math.Ceiling(bottom-viewport.ClientSize.Height)));float visibleBottom=bottom+viewport.AutoScrollPosition.Y;if(visibleBottom< -1||visibleBottom>viewport.ClientSize.Height+1)throw new Exception("Page bottom cannot be reached by scrolling.");viewport.AutoScrollPosition=new Point(-saved.X,-saved.Y);
    File.AppendAllText(Path.Combine(output,"scroll-bounds.tsv"),view+"\t"+dpi+"\t"+command+"\t"+top+"\t"+bottom+"\t"+canvas.Height+"\t"+viewport.AutoScrollMinSize.Height+Environment.NewLine);
   }if(view!=NotationView.DatViewport&&dos){if(!canvas.UsesOriginalZoomFrame)throw new Exception("Missing DOS framing in "+view);float rawX=1200,rawY=400;var world=canvas.PageDocument.Projection.Point(rawX,rawY);var pixel=new PointF((world.X+canvas.CameraOffset.X)*canvas.RenderScale,(world.Y+canvas.CameraOffset.Y)*canvas.RenderScale);var restored=NativeWorkspaceGuides.RawAt(canvas,pixel);if(Math.Abs(restored.X-rawX)>.02||Math.Abs(restored.Y-rawY)>.02)throw new Exception("Raw pointer round trip differs.");float fit=canvas.RenderScale*NativeDosViewport.Divisor/30;float expectedX=(rawX/NativeDosViewport.Divisor+NativeDosViewport.OriginX)*fit,expectedY=(-rawY/NativeDosViewport.Divisor+NativeDosViewport.OriginY-97)*fit;if(Math.Abs(pixel.X-expectedX)>.02||Math.Abs(pixel.Y-expectedY)>.02)throw new Exception("DOS-to-hi-res framing differs.");}else if(view!=NotationView.DatViewport&&canvas.OriginalZoomFrame)throw new Exception("Full-page option used DOS framing.");}
   var note=score.Items.First(i=>i.Code==1);BeginEdit(note);Execute("Z 2");short previousX=NativeDosViewport.OriginX,previousY=NativeDosViewport.OriginY,previousDivisor=NativeDosViewport.Divisor;var previousCamera=canvas.CameraOffset;Point previousScroll=viewport.AutoScrollPosition;var next=score.Items.First(i=>i.Code==1&&i!=note);SelectByMouse(next);if(previousX!=NativeDosViewport.OriginX||previousY!=NativeDosViewport.OriginY||canvas.CameraOffset!=previousCamera||viewport.AutoScrollPosition!=previousScroll)throw new Exception("Mouse selection repositioned the score.");Execute("3 27");if(!canvas.EditModified)throw new Exception("Pending-edit test did not mutate its private item.");Execute("ZZ 3");Execute("ZR 15");if(previousX!=NativeDosViewport.OriginX||previousY!=NativeDosViewport.OriginY||previousDivisor!=NativeDosViewport.Divisor)throw new Exception("Pending edit accepted viewport changes.");AbortCurrent();ExitEdit(false);if(!original.SequenceEqual(score.Encode()))throw new Exception("Edit zoom/abort changed notation.");
   if(!dos&&dpi==1.75f&&view!=NotationView.DatViewport){Execute("FIT");Execute("Z 2");Message("");viewport.AutoScrollPosition=Point.Empty;Application.DoEvents();using(var image=new Bitmap(ClientSize.Width,ClientSize.Height)){DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(output,"full-top-"+view+".png"));}}
   if(dpi==1.75f){using(var bitmap=new Bitmap(Math.Max(1,Math.Min(2000,canvas.Width)),Math.Max(1,Math.Min(1200,canvas.Height)))){canvas.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(output,(dos?"dos-":"full-")+view+".png"));}}
  }
  NativeZoomFraming.SetDefinitions(true,false);Execute("ZZ");if(NativeDosViewport.ZoomFactor!=3)throw new Exception("Tom's Help ZZ default differs.");Execute("Z 2");Execute("Z");if(NativeDosViewport.ZoomFactor!=1)throw new Exception("Tom's Help bare Z did not reset.");NativeScoreBehaviour.Set(true,false);Execute("ZZ");if(NativeDosViewport.ZoomFactor!=2)throw new Exception("Strict preset lost executable ZZ default.");NativeZoomFraming.SetDefinitions(false,false);
  NativeScoreBehaviour.Set(true,false);NativeZoomFraming.Set(false,false);if(!NativeZoomFraming.Dos)throw new Exception("Strict preset lost DOS framing.");NativeScoreBehaviour.Set(false,false);Console.WriteLine("PASS 216 cross-view Z/ZZ/pan transitions; four modes, two framings, three DPI scales; raw pointer/viewport transforms; 24 edit/selection/abort workflows; unchanged MUS; strict preset.");
 }finally{NativeScoreBehaviour.Set(false,false);NativeZoomFraming.Set(dosBefore,false);canvas.OriginalZoomFrame=false;NativeNotationView.Set(modeBefore,false);canvas.LayoutScore();}}
 }
 public static class NativeZoomFramingChecks {public static int Run(string[] args){try{using(var editor=new Editor(args[1],args[2])){editor.Show();Application.DoEvents();editor.CheckZoomFramings(args[3]);editor.Close();}return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}}
}
